//! The memo path of the G-SP spike bench (`benches/spike.rs`, `memo.*` families) checked against cold
//! evaluation, non-timing, class S only (the L/XL fixtures are generated by the spike run).
//!
//! The bench measures `ew_derive::MemoStore`; this test runs the same steps on a fork of a store warmed on the
//! baseline, under `Oracle::Every`: after a hit, an unrelated edit (a conductor colour), a move and a wire,
//! the memoised `potential_partition`, `page_local_nets` of every page and `wire_props_of` of every potential
//! equal the values of a cold `Q`, the oracle finds no mismatch, and the engine counters show a memo path: a
//! hit without re-execution, an unrelated edit that does not re-execute the partition, edits that re-execute
//! the families they invalidate.

use ew_api::{MemoMode, Session, SessionOptions};
use ew_commands::commands::{Connect, EndpointParam, KindName, MoveReps, SetFields};
use ew_commands::testkit::seeded_ids;
use ew_derive::{Counters, MemoStore, Oracle, PageLocalNets, PotentialPartition, Q, WirePropsOf};
use ew_ids::Id;
use ew_model::{AnyKey, Model};
use ew_schema::{Page, Record};
use ew_testkit::synth::{self, Handles, SizeClass};
use ew_units::Pt2;

/// Every this-many-th potential goes through the oracle (see [`assert_matches_cold`]).
const ORACLE_STRIDE: usize = 150;

/// A session without memo work: the commit pipeline alone, as in the bench.
fn session(model: &Model) -> Session {
    Session::new(
        model.clone(),
        SessionOptions {
            ids: Some(seeded_ids(1)),
            memo: MemoMode::Off,
            ..Default::default()
        },
    )
}

/// The memoised reads of the bench's targets through `store`: the partition, the local nets of every page and
/// the wire properties of every potential.
fn read_all(store: &MemoStore, pages: &[Id<Page>]) {
    let q = store.query();
    let part = q.get::<PotentialPartition>(());
    for page in pages {
        q.get::<PageLocalNets>(*page);
    }
    for p in part.potentials() {
        q.get::<WirePropsOf>(p.id);
    }
}

/// Asserts that every memoised value `store` hands out equals the cold value on `model`, and that the oracle
/// found no mismatch.
///
/// The store is in `Oracle::Every` mode, but an oracle check evaluates the family cold, and a cold
/// `wire_props_of` derives the partition: with hundreds of potentials every one of them through the oracle
/// would take minutes in a debug build. So the oracle checks the partition, the local nets and every
/// `ORACLE_STRIDE`-th potential; the others are read with the oracle off and compared with the cold values here.
fn assert_matches_cold(store: &MemoStore, model: &Model, pages: &[Id<Page>], what: &str) {
    store.set_oracle(Oracle::Every);
    let q = store.query();
    let cold = Q::new(model);
    let memoised = q.get::<PotentialPartition>(());
    assert_eq!(
        *memoised,
        *cold.get::<PotentialPartition>(()),
        "{what}: the memoised potential_partition equals the cold one"
    );
    for page in pages {
        assert_eq!(
            *q.get::<PageLocalNets>(*page),
            *cold.get::<PageLocalNets>(*page),
            "{what}: the memoised page_local_nets of {page:?} equals the cold one"
        );
    }
    assert!(
        memoised.potential_count() > 0,
        "{what}: the fixture has potentials"
    );
    for (i, p) in memoised.potentials().enumerate() {
        store.set_oracle(if i % ORACLE_STRIDE == 0 {
            Oracle::Every
        } else {
            Oracle::Off
        });
        assert_eq!(
            *q.get::<WirePropsOf>(p.id),
            *cold.get::<WirePropsOf>(p.id),
            "{what}: the memoised wire_props_of {:?} equals the cold one",
            p.id
        );
    }
    store.set_oracle(Oracle::Every);
    assert!(
        store.take_mismatches().is_empty(),
        "{what}: the oracle found no mismatch"
    );
}

/// The keys the session's last commits touched (what the bench's memo step hands to `advance`).
fn touched(session: &mut Session) -> Vec<AnyKey> {
    session
        .drain_changes()
        .into_iter()
        .flat_map(|c| c.touched_keys)
        .collect()
}

/// A load representation moved by six by three grid steps.
fn move_cmd(handles: &Handles) -> MoveReps {
    MoveReps {
        items: Vec::new(),
        steps: None,
        reps: vec![handles.load_reps[0]],
        delta: Pt2::new(handles.grid.at(6).unwrap(), handles.grid.at(3).unwrap()),
        page: None,
    }
}

/// A wire between the first two free CPs of the first page that has two; with that page's index.
fn wire_cmd(handles: &Handles) -> (Connect, usize) {
    let p = (0..handles.pages.len())
        .find(|p| handles.free_cps[*p].len() >= 2)
        .expect("a page with two free CPs");
    let (a, b) = (handles.free_cps[p][0], handles.free_cps[p][1]);
    let cmd = Connect {
        a: EndpointParam::Cp {
            function: a.0,
            idx: a.1,
        },
        b: EndpointParam::Cp {
            function: b.0,
            idx: b.1,
        },
        page: Some(handles.pages[p]),
        route: Vec::new(),
        kind: Default::default(),
    };
    (cmd, p)
}

/// The counters of `family` in the store's last commit.
fn counters(store: &MemoStore, family: &str) -> Counters {
    store.commit_stats().family(family)
}

/// The G-SP spike's companion: in the deep nightly with the bench's other checks (test audit g7). Per gate the
/// same families after a move, a wire and a colour edit are checked by `ew-api`'s
/// `memo_equals_cold_over_every_state` and `ew-derive`'s `incremental_partition_equals_cold`.
#[test]
#[ignore = "deep nightly (CI-N-02): the spike bench's memo path under Oracle::Every on the synthetic S project"]
fn nightly_memoised_connectivity_equals_cold_after_hit_unrelated_edit_move_and_wire() {
    let g = synth::project(SizeClass::S, 1);
    let handles = g.handles.clone();
    let (conductor, colour) = g
        .records
        .iter()
        .find_map(|r| match r {
            Record::Conductor(c) => Some((
                c.id,
                serde_json::to_value(&c.colour).expect("a colour serialises"),
            )),
            _ => None,
        })
        .expect("the fixture has a conductor");
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    let pages = &handles.pages;

    // The store warmed on the baseline: the first execution of every target.
    let warm = MemoStore::new(&model);
    read_all(&warm, pages);
    let first = counters(&warm, "potential_partition");
    assert!(
        first.re_executions >= 1,
        "the first read executes the partition: {first:?}"
    );

    // A hit: a read at the revision the store is at.
    let fork = warm.fork();
    fork.set_oracle(Oracle::Every);
    assert_matches_cold(&fork, &model, pages, "hit");
    let c = counters(&fork, "potential_partition");
    assert!(c.hits > 0, "a hit: {c:?}");
    assert_eq!(
        c.re_executions, 0,
        "a hit does not re-execute the partition: {c:?}"
    );

    // An unrelated edit: the conductor colour is not read by the partition.
    let fork = warm.fork();
    fork.set_oracle(Oracle::Every);
    let mut s = session(&model);
    let new_colour = if colour == serde_json::json!(["BK"]) {
        "WH"
    } else {
        "BK"
    };
    s.execute(&SetFields {
        kind: KindName::Conductor,
        targets: vec![conductor.cast()],
        path: "colour".into(),
        value: serde_json::json!([new_colour]),
        copies: Vec::new(),
    })
    .expect("conductor colour accepted");
    let after = s.world().model;
    fork.advance(&after, &touched(&mut s));
    assert_matches_cold(&fork, &after, pages, "unrelated");
    let c = counters(&fork, "potential_partition");
    assert_eq!(
        c.re_executions, 0,
        "an unrelated edit does not re-execute the partition: {c:?}"
    );

    // A move of a load representation.
    let fork = warm.fork();
    fork.set_oracle(Oracle::Every);
    let mut s = session(&model);
    s.execute(&move_cmd(&handles)).expect("move accepted");
    let after = s.world().model;
    fork.advance(&after, &touched(&mut s));
    assert_matches_cold(&fork, &after, pages, "move");
    let c = counters(&fork, "potential_partition");
    assert!(c.re_executions >= 1, "the move re-executes the partition: {c:?}");

    // A new wire: the partition, the page's local nets and the wire properties follow.
    let fork = warm.fork();
    fork.set_oracle(Oracle::Every);
    let mut s = session(&model);
    let (wire, p) = wire_cmd(&handles);
    s.execute(&wire).expect("wire accepted");
    let after = s.world().model;
    fork.advance(&after, &touched(&mut s));
    assert_matches_cold(&fork, &after, pages, "wire");
    let c = counters(&fork, "potential_partition");
    assert!(c.re_executions >= 1, "the wire re-executes the partition: {c:?}");
    let c = counters(&fork, "page_local_nets");
    assert!(
        c.re_executions >= 1,
        "the wire re-executes the local nets of page {p}: {c:?}"
    );

    // The baseline store did not move: the forks evolved independently.
    assert_matches_cold(&warm, &model, pages, "baseline after the forks");
}
